using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap a REST API using HttpClient.
/// Uses constructor injection for HttpClient and ILogger — both are resolved
/// automatically by the DI container and never appear in the tool schema.
/// </summary>
[McpServerToolType]
internal class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all items from the API. Returns JSON array.")]
    public async Task<string> ListItems(
        [Description("Maximum number of items to return (1-100)")] int limit = 20,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing items with limit={Limit}", limit);
        var response = await httpClient.GetStringAsync($"/items?limit={limit}", cancellationToken);
        return response;
    }

    [McpServerTool, Description("Get a single item by its unique identifier.")]
    public async Task<string> GetItem(
        [Description("The unique identifier of the item")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching item {Id}", id);
        var response = await httpClient.GetAsync($"/items/{id}", cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
        }

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }

    [McpServerTool, Description("Create a new item with the given name and description.")]
    public async Task<string> CreateItem(
        [Description("Name for the new item")] string name,
        [Description("Optional description")] string? description = null,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating item {Name}", name);

        var payload = JsonSerializer.Serialize(new { name, description }, JsonOptions);
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/items", content, cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
        }

        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        return body;
    }

    [McpServerTool(Destructive = true), Description("Delete an item by its unique identifier.")]
    public async Task<string> DeleteItem(
        [Description("The unique identifier of the item to delete")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Deleting item {Id}", id);
        var response = await httpClient.DeleteAsync($"/items/{id}", cancellationToken);

        return response.IsSuccessStatusCode
            ? $"Item {id} deleted successfully."
            : $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
    }
}

